  'button-tinted': 'DsButton(\n  variant: .tinted,\n  leading: const DsIcon(DsIcons.calendar),\n  onPressed: () {},\n  child: const Text(\'Add to calendar\'),\n),\nDsButton(\n  variant: .tinted,\n  size: .sm,\n  onPressed: () {},\n  child: const Text(\'Follow\'),\n),\nDsButton.icon(\n  variant: .tinted,\n  icon: const DsIcon(DsIcons.share),\n  semanticLabel: \'Share\',\n  onPressed: () {},\n)',
  'button-variants': 'DsButton(onPressed: () {}, child: const Text(\'Primary\')),\nDsButton(\n  variant: .secondary,\n  onPressed: () {},\n  child: const Text(\'Secondary\'),\n),\nDsButton(\n  variant: .tinted,\n  onPressed: () {},\n  child: const Text(\'Tinted\'),\n),\nDsButton(\n  variant: .ghost,\n  onPressed: () {},\n  child: const Text(\'Ghost\'),\n),\nDsButton(\n  variant: .dangerSoft,\n  onPressed: () {},\n  child: const Text(\'Remove\'),\n),\nDsButton(\n  variant: .danger,\n  onPressed: () {},\n  child: const Text(\'Delete\'),\n),\nDsButton(\n  variant: .neutral,\n  onPressed: () {},\n  child: const Text(\'Neutral\'),\n)',
  'calendar-custom': 'DsCalendar(\n  value: _day,\n  onChanged: (d) => setState(() => _day = d),\n  style: DsCalendarStyle(\n    daySize: 36,\n    dayRadius: BorderRadius.circular(999),\n    columnGap: 2,\n  ),\n)',
  'calendar-limits': '// Weekdays, for 60 days:\nfinal today = DateTime.now();\nreturn DsCalendar(\n  semanticLabel: \'Visit\',\n  value: _visit,\n  firstDate: today,\n  lastDate: today.add(const Duration(days: 60)),\n  selectableDayPredicate: (d) =>\n      d.weekday != DateTime.saturday && d.weekday != DateTime.sunday,\n  onChanged: (d) => setState(() => _visit = d),\n)',
  'calendar-locale': 'Localizations.override(\n  context: context,\n  locale: const Locale(\'en\', \'US\'),\n  child: DsCalendar(\n    value: _day,\n    onChanged: (d) => setState(() => _day = d),\n  ),\n)',
  'calendar-outside': 'DsCalendar(\n  showOutsideDays: true,\n  value: _day,\n  onChanged: (d) => setState(() => _day = d),\n)',
  'calendar-overview': 'DsCalendar(\n  semanticLabel: \'Due date\',\n  value: _due,\n  onChanged: (d) => setState(() => _due = d),\n)',
  'calendar-range': '// Two months when they fit:\nfinal wide = c.maxWidth >= 560;\nreturn DsRangeCalendar(\n  semanticLabel: \'Stay\',\n  months: wide ? 2 : 1,\n  value: _stay,\n  firstDate: DateTime.now(),\n  onChanged: (r) => setState(() => _stay = r),\n)',
  'card-custom': '// Theme colors:\nfinal k = DsTheme.colorsOf(context);\nreturn DsCard(\n  style: DsCardStyle(\n    background: k.accentTint,\n    shadows: const [],\n    padding: const EdgeInsets.all(20),\n    borderRadius: BorderRadius.circular(20),\n  ),\n  child: Text(\n    \'Your trial ends in 5 days. Pick a plan to keep your \'\n    \'projects.\',\n    style: TextStyle(color: k.accentText),\n  ),\n)',
  'card-dashed': '// In a build method:\nfinal t = DsTheme.of(context);\nreturn DsCard(\n  dashed: true,\n  onPressed: () {},\n  semanticLabel: \'Add a widget\',\n  child: SizedBox(\n    height: 96,\n    child: Column(\n      mainAxisAlignment: MainAxisAlignment.center,\n      spacing: 6,\n      children: [\n        DsIcon(DsIcons.plus, color: t.colors.textMuted),\n        Text(\n          \'Add a widget\',\n          style: t.typography.small.copyWith(\n            color: t.colors.textMuted,\n          ),\n        ),\n      ],\n    ),\n  ),\n)',
  'card-overview': '// In a build method:\nfinal t = DsTheme.of(context);\nfinal muted = t.typography.small.copyWith(color: t.colors.textMuted);\nreturn DsCard(\n  child: Column(\n    crossAxisAlignment: CrossAxisAlignment.stretch,\n    spacing: 12,\n    children: [\n      Row(\n        children: [\n          Expanded(\n            child: Text(\n              \'Storage\',\n              style: t.typography.heading.copyWith(color: t.colors.text),\n            ),\n          ),\n          const DsBadge(status: .warning, label: Text(\'92% full\')),\n        ],\n      ),\n      const DsProgressBar(value: .92, semanticLabel: \'Storage used\'),\n      Text(\'18.4 GB of 20 GB used. Large files: 6.2 GB.\', style: muted),\n      Align(\n        alignment: AlignmentDirectional.centerStart,\n        child: DsButton(\n          variant: .secondary,\n          size: .sm,\n          onPressed: () {},\n          child: const Text(\'Manage storage\'),\n        ),\n      ),\n    ],\n  ),\n)',
  'card-padding': 'DsCard(\n  style: const DsCardStyle(padding: EdgeInsets.zero),\n  child: DsEmptyState(\n    icon: const DsIcon(DsIcons.folder),\n    title: const Text(\'No files yet\'),\n    description: const Text(\n      \'Upload a brief or drop files here to share them with \'\n      \'the team.\',\n    ),\n    actions: [\n      DsButton(\n        size: .sm,\n        leading: const DsIcon(DsIcons.upload),\n        onPressed: () {},\n        child: const Text(\'Upload\'),\n      ),\n    ],\n  ),\n)',
  'card-pressable': 'DsCard(\n  semanticLabel: \'Q4 roadmap, 12 tasks, 3 days left\',\n  onPressed: () {},\n  child: Column(\n    crossAxisAlignment: CrossAxisAlignment.start,\n    spacing: 12,\n    children: [\n      const DsAvatar(initials: \'Q4\', size: .sm, toneIndex: 1),\n      Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        spacing: 2,\n        children: [\n          Text(\'Q4 roadmap\', style: titleStyle),\n          Text(\'12 tasks · 3 days left\', style: mutedStyle),\n        ],\n      ),\n      const DsProgressBar(value: .58),\n    ],\n  ),\n)',
  'checkbox-custom': 'DsCheckbox(\n  value: true,\n  onChanged: (v) {},\n  style: DsCheckboxStyle(\n    size: 20,\n    borderRadius: BorderRadius.circular(999),\n    selected: const DsCheckboxStyle(\n      background: Color(0xFF0B6E4F),\n    ),\n  ),\n  label: const Text(\'Round and green\'),\n),\nDsCheckboxTheme(\n  data: const DsCheckboxThemeData(\n    style: DsCheckboxStyle(gap: 8),\n  ),\n  child: DsCheckbox(\n    value: false,\n    onChanged: (v) {},\n    label: const Text(\'Tighter label gap\'),\n  ),\n)',
  'checkbox-description': 'DsCheckbox(\n  value: _public,\n  onChanged: (v) => setState(() => _public = v!),\n  label: const Text(\'Public profile\'),\n  description: const Text(\n    \'Anyone with the link can see your name and projects.\',\n  ),\n),\nDsCheckbox(\n  value: _comments,\n  onChanged: (v) => setState(() => _comments = v!),\n  label: const Text(\'Allow comments\'),\n  description: const Text(\'Members of the workspace can reply.\'),\n)',
  'checkbox-disabled': 'const DsCheckbox(\n  value: true,\n  onChanged: null,\n  label: Text(\'Included in plan\'),\n),\nconst DsCheckbox(\n  value: false,\n  onChanged: null,\n  label: Text(\'Single sign-on\'),\n)',
  'checkbox-error': 'DsField(\n  errorText: _tried && !_accepted\n      ? \'Accept the terms to create your workspace.\'\n      : null,\n  child: DsCheckbox(\n    value: _accepted,\n    onChanged: (v) => setState(() => _accepted = v!),\n    label: const Text(\'I accept the terms of service\'),\n  ),\n),\nDsButton(\n  onPressed: () => setState(() => _tried = true),\n  child: const Text(\'Create workspace\'),\n)',
  'checkbox-overview': 'DsCheckbox(\n  value: _digest,\n  onChanged: (v) => setState(() => _digest = v!),\n  label: const Text(\'Weekly summary email\'),\n),\nDsCheckbox(\n  value: _mentions,\n  onChanged: (v) => setState(() => _mentions = v!),\n  label: const Text(\'When someone mentions me\'),\n),\nDsCheckbox(\n  value: _assigned,\n  onChanged: (v) => setState(() => _assigned = v!),\n  label: const Text(\'When a task is assigned to me\'),\n)',
  'checkbox-select-all': 'DsCheckbox(\n  tristate: true,\n  value: _all,\n  onChanged: (_) => setState(() {\n    final next = _all != true;\n    _files.updateAll((name, on) => next);\n  }),\n  label: const Text(\'Select all\'),\n),\nfor (final name in _files.keys)\n  Padding(\n    padding: const EdgeInsetsDirectional.only(start: 30),\n    child: DsCheckbox(\n      value: _files[name]!,\n      onChanged: (v) => setState(() => _files[name] = v!),\n      label: Text(name),\n    ),\n  )',
  'chip-custom': 'DsChip(\n  label: const Text(\'Rounded\'),\n  selected: true,\n  onChanged: (on) {},\n  style: DsChipStyle(\n    height: 28,\n    borderRadius: BorderRadius.circular(999),\n    padding: const EdgeInsetsDirectional.symmetric(\n      horizontal: 12,\n    ),\n  ),\n),\nDsChip(\n  label: const Text(\'Brand fill\'),\n  selected: true,\n  onChanged: (on) {},\n  style: const DsChipStyle(\n    showCheck: false,\n    selected: DsChipStyle(\n      background: Color(0xFF0B6E4F),\n      foreground: Color(0xFFFFFFFF),\n    ),\n  ),\n)',
  'chip-disabled': 'const DsChip(\n  label: Text(\'Archived\'),\n  selected: false,\n  onChanged: null,\n),\nconst DsChip(\n  label: Text(\'My tasks\'),\n  selected: true,\n  onChanged: null,\n)',
  'chip-icons': 'DsChip(\n  leading: const DsIcon(DsIcons.user),\n  label: const Text(\'Assigned to me\'),\n  selected: _mine,\n  onChanged: (on) => setState(() => _mine = on),\n),\nDsChip(\n  leading: const DsIcon(DsIcons.clock),\n  label: const Text(\'Due this week\'),\n  selected: _due,\n  onChanged: (on) => setState(() => _due = on),\n),\nDsChip(\n  leading: const DsIcon(DsIcons.mail),\n  label: const Text(\'Unread\'),\n  selected: _unread,\n  onChanged: (on) => setState(() => _unread = on),\n)',
  'chip-overview': 'for (final label in _labels)\n  DsChip(\n    label: Text(label),\n    selected: _on.contains(label),\n    onChanged: (on) =>\n        setState(() => on ? _on.add(label) : _on.remove(label)),\n  )',
  'chip-single': 'DsChoiceChips<String>(\n  value: _filter,\n  onChanged: (v) => setState(() => _filter = v),\n  semanticLabel: \'Show\',\n  options: const [\n    DsChipOption(value: \'all\', label: Text(\'All\')),\n    DsChipOption(value: \'unread\', label: Text(\'Unread\')),\n    DsChipOption(value: \'flagged\', label: Text(\'Flagged\')),\n    DsChipOption(value: \'mentions\', label: Text(\'Mentions\')),\n    DsChipOption(value: \'attachments\', label: Text(\'With attachments\')),\n    DsChipOption(value: \'archived\', label: Text(\'Archived\')),\n  ],\n)',
  'colors-bright': 'DsThemeData(seed: DsSeed.color(const Color(0xFFFFC72C)))',
  'colors-playground': 'DsThemeData(seed: DsSeed.color(_brand))',
  'colors-seed': 'DsThemeData(seed: DsSeed.color(const Color(0xFF0F766E)))',
  'corners-continuous': '// A card-like box: continuous corners, ring and fill concentric.\nContainer(\n  width: 160,\n  height: 96,\n  decoration: DsBoxDecoration(\n    color: k.surface,\n    borderRadius: BorderRadius.circular(r.card),\n    shadows: t.shadows.surface,\n  ),\n),\n// A capsule keeps true half-circle ends.\nContainer(\n  width: 160,\n  height: 40,\n  decoration: DsBoxDecoration(\n    color: k.accent,\n    borderRadius: BorderRadius.circular(DsRadii.pill),\n  ),\n)',
  'corners-decoration': '// A well: an inner outline and a soft inset shadow at the top.\nContainer(\n  width: 160,\n  height: 56,\n  decoration: DsBoxDecoration(\n    color: k.field,\n    borderRadius: BorderRadius.circular(r.control(56)),\n    shadows: [\n      DsShadow.innerRing(k.borderField),\n      DsShadow(\n        color: k.press,\n        offset: const Offset(0, 2),\n        blur: 4,\n        inset: true,\n      ),\n    ],\n  ),\n),\n// A ring with a gap, like CSS outline-offset.\nContainer(\n  width: 160,\n  height: 56,\n  decoration: DsBoxDecoration(\n    color: k.accent,\n    borderRadius: BorderRadius.circular(r.control(56)),\n    shadows: [DsShadow.outline(k.focus, width: 2, gap: 2)],\n  ),\n),\n// A header with a bottom line that takes no layout space.\nContainer(\n  width: 160,\n  height: 56,\n  decoration: DsBoxDecoration(\n    color: k.sidebar,\n    shadows: [DsShadow.bottomLine(k.borderControl)],\n  ),\n)',
  'corners-hairline':
      '// A separator: one device pixel wide.\nDsLine(color: k.border)',
  'corners-style': 'DsThemeData(cornerStyle: style)',
  'customizing-pressable': 'DsPressable(\n  onPressed: () => setState(() => _plan = name),\n  selected: _plan == name,\n  semanticLabel: \'\$name, \$price, \$note\',\n  builder: (context, states, _) {\n    final selected = _plan == name;\n    final hovered = states.contains(WidgetState.hovered);\n    final corners = BorderRadius.circular(t.radii.card);\n    return DsFocusRing(\n      focused: states.contains(WidgetState.focused),\n      borderRadius: corners,\n      child: AnimatedContainer(\n        duration: t.motion.toneDuration,\n        curve: t.motion.toneCurve,\n        width: 160,\n        padding: const EdgeInsets.all(DsSpace.s16),\n        decoration: DsBoxDecoration(\n          color: selected ? k.selection : k.surface,\n          borderRadius: corners,\n          shadows: [\n            DsShadow.innerRing(\n              selected\n                  ? k.onSelection\n                  : (hovered ? k.borderField : k.border),\n              width: selected ? 2 : 1,\n            ),\n          ],\n        ),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          spacing: 4,\n          children: [\n            Text(name, style: y.labelStrong.copyWith(color: k.text)),\n            Text(\n              price,\n              style: y.numeric(y.title).copyWith(color: k.text),\n            ),\n            Text(note, style: y.caption.copyWith(color: k.textMuted)),\n          ],\n        ),\n      ),\n    );\n  },\n)',
  'customizing-states': 'DsButton(\n  variant: .ghost,\n  leading: const DsIcon(DsIcons.trash),\n  style: DsButtonStyle(\n    foreground: k.textMuted,\n    hovered: DsButtonStyle(\n      foreground: k.danger.text,\n      background: k.danger.tint,\n    ),\n    pressed: DsButtonStyle(background: k.danger.tintPress),\n  ),\n  onPressed: () {},\n  child: const Text(\'Discard draft\'),\n)',
  'customizing-style': 'DsButton(\n  style: DsButtonStyle.solid(\n    background: const Color(0xFF7C3AED),\n    foreground: const Color(0xFFFFFFFF),\n    brightness: DsTheme.of(context).brightness,\n  ),\n  onPressed: () {},\n  child: const Text(\'Upgrade to Pro\'),\n),\nDsButton(\n  variant: .secondary,\n  style: DsButtonStyle(\n    borderRadius: BorderRadius.circular(999),\n    shadows: const [],\n  ),\n  onPressed: () {},\n  child: const Text(\'Compare plans\'),\n)',
  'customizing-theme': 'DsButtonTheme(\n  data: DsButtonThemeData(\n    size: .sm,\n    variant: .ghost,\n    variants: {\n      DsButtonVariant.ghost: DsButtonStyle(\n        foreground: k.textMuted,\n        hovered: DsButtonStyle(foreground: k.text),\n      ),\n    },\n  ),\n  child: Wrap(\n    spacing: 4,\n    runSpacing: 4,\n    alignment: WrapAlignment.center,\n    children: [\n      DsButton(\n        leading: const DsIcon(DsIcons.share),\n        onPressed: () {},\n        child: const Text(\'Share\'),\n      ),\n      DsButton(\n        leading: const DsIcon(DsIcons.link),\n        onPressed: () {},\n        child: const Text(\'Copy link\'),\n      ),\n      DsButton(\n        leading: const DsIcon(DsIcons.upload),\n        onPressed: () {},\n        child: const Text(\'Export\'),\n      ),\n    ],\n  ),\n)',
  'date-picker-custom': 'DsDatePicker(\n  value: _launch,\n  onChanged: (d) => setState(() => _launch = d),\n  semanticLabel: \'Launch date\',\n  style: DsDatePickerStyle(\n    buttonStyle: const DsButtonStyle(\n      foreground: Color(0xFF0B6E4F),\n    ),\n    calendarStyle: DsCalendarStyle(\n      dayRadius: BorderRadius.circular(6),\n    ),\n  ),\n)',
  'date-picker-limits': 'DsField(\n  label: const Text(\'Delivery date\'),\n  description: const Text(\n    \'Weekdays only, within the next 60 days.\',\n  ),\n  child: DsDatePicker(\n    value: _delivery,\n    firstDate: today.add(const Duration(days: 1)),\n    lastDate: today.add(const Duration(days: 60)),\n    selectableDayPredicate: (day) =>\n        day.weekday != DateTime.saturday &&\n        day.weekday != DateTime.sunday,\n    onChanged: (d) => setState(() => _delivery = d),\n  ),\n)',
  'date-picker-overview': 'DsField(\n  label: const Text(\'Due date\'),\n  description: const Text(\'Type it or pick it.\'),\n  child: DsDatePicker(\n    value: _due,\n    firstDate: today,\n    onChanged: (d) => setState(() => _due = d),\n  ),\n)',
  'date-picker-range': 'DsField(\n  label: const Text(\'Report period\'),\n  child: DsDateRangePicker(\n    value: _period,\n    lastDate: today.add(const Duration(days: 365)),\n    onChanged: (r) => setState(() => _period = r),\n  ),\n)',
  'date-picker-states': 'SizedBox(\n  width: 240,\n  child: DsField(\n    label: const Text(\'Contract start\'),\n    child: DsDatePicker(\n      value: DateTime(2026, 3, 1),\n      onChanged: (d) {},\n      readOnly: true,\n    ),\n  ),\n),\nSizedBox(\n  width: 240,\n  child: DsField(\n    label: const Text(\'Renewal date\'),\n    child: DsDatePicker(\n      value: DateTime(2027, 3, 1),\n      onChanged: null,\n    ),\n  ),\n)',
  'date-picker-typing': 'DsField(\n  label: const Text(\'Invoice date\'),\n  child: DsDatePicker(\n    value: _invoiceDate,\n    onChanged: (d) => setState(() => _invoiceDate = d),\n  ),\n)',
  'dialog-anatomy': 'DsDialog(\n  icon: const DsIcon(DsIcons.mail),\n  title: const Text(\'Invite your team\'),\n  description: const Text(\n    \'Members can see every project in Northwind and comment on tasks.\',\n  ),\n  actions: [\n    DsButton(\n      variant: .secondary,\n      onPressed: () {},\n      child: const Text(\'Later\'),\n    ),\n    DsButton(onPressed: () {}, child: const Text(\'Send invites\')),\n  ],\n)',
  'dialog-confirm': 'DsButton(\n  onPressed: () async {\n    final publish = await showDsConfirm(\n      context: context,\n      title: \'Publish changes?\',\n      description: \'Everyone with access to the help center sees them.\',\n      confirmLabel: \'Publish\',\n      cancelLabel: \'Not yet\',\n    );\n    if (mounted) setState(() => _published = publish);\n  },\n  child: const Text(\'Publish\'),\n)',
  'dialog-custom': 'DsButton(\n  variant: .secondary,\n  onPressed: () async {\n    var name = _name;\n    final rename = await showDsDialog<bool>(\n      context: context,\n      builder: (context) => DsDialog(\n        title: const Text(\'Rename project\'),\n        description: DsTextField(\n          initialValue: name,\n          autofocus: true,\n          semanticLabel: \'Project name\',\n          onChanged: (v) => name = v,\n          onSubmitted: (_) => Navigator.of(context).pop(true),\n        ),\n        actions: [\n          DsButton(\n            variant: .secondary,\n            onPressed: () => Navigator.of(context).pop(false),\n            child: const Text(\'Cancel\'),\n          ),\n          DsButton(\n            onPressed: () => Navigator.of(context).pop(true),\n            child: const Text(\'Rename\'),\n          ),\n        ],\n      ),\n    );\n    if (rename == true && mounted && name.trim().isNotEmpty) {\n      setState(() => _name = name.trim());\n    }\n  },\n  child: const Text(\'Rename…\'),\n)',
  'dialog-custom-theme': 'DsDialogTheme(\n  data: DsDialogThemeData(\n    style: DsDialogStyle(\n      width: 420,\n      borderRadius: BorderRadius.circular(24),\n      padding: const EdgeInsets.all(28),\n    ),\n  ),\n  child: Builder(\n    builder: (context) => DsButton(\n      variant: .secondary,\n      onPressed: () => showDsConfirm(\n        context: context,\n        title: \'Leave the workspace?\',\n        description:\n            \'You lose access to its projects until someone \'\n            \'invites you again.\',\n        confirmLabel: \'Leave\',\n        destructive: true,\n      ),\n      child: const Text(\'Leave workspace\'),\n    ),\n  ),\n)',
  'dialog-overview': 'DsButton(\n  variant: .dangerSoft,\n  leading: const DsIcon(DsIcons.trash),\n  onPressed: () async {\n    final delete = await showDsConfirm(\n      context: context,\n      title: \'Delete project?\',\n      description:\n          \'Northwind website and its 48 tasks will be deleted. This \'\n          \'cannot be undone.\',\n      confirmLabel: \'Delete\',\n      destructive: true,\n      icon: const DsIcon(DsIcons.trash),\n    );\n    if (delete && context.mounted) {\n      showDsToast(context: context, title: \'Project deleted\');\n    }\n  },\n  child: const Text(\'Delete project\'),\n)',
  'divider-custom': 'DsTheme.colorsOf(context);\nreturn Column(\n  spacing: 16,\n  children: [\n    DsDivider(\n      style: DsDividerStyle(\n        thickness: 2,\n        color: k.accentText,\n      ),\n    ),\n    DsDividerTheme(\n      data: DsDividerThemeData(\n        style: DsDividerStyle(color: k.borderControl),\n      ),\n      child: const DsDivider(),\n    ),\n  ],\n)',
  'divider-inset': '// Starts under the label: icon 16 + gap 12.\nconst DsDivider(indent: 28)',
  'divider-overview': 'Column(\n  crossAxisAlignment: CrossAxisAlignment.start,\n  spacing: 12,\n  children: [\n    Text(\'Account\', style: text),\n    const DsDivider(),\n    Text(\'Notifications\', style: text),\n  ],\n)',
  'divider-vertical': 'IntrinsicHeight(\n  child: Row(\n    mainAxisSize: MainAxisSize.min,\n    spacing: 12,\n    children: [\n      DsButton(\n        variant: .ghost,\n        onPressed: () {},\n        child: const Text(\'Edit\'),\n      ),\n      const DsDivider.vertical(indent: 8, endIndent: 8),\n      DsButton(\n        variant: .ghost,\n        onPressed: () {},\n        child: const Text(\'Share\'),\n      ),\n    ],\n  ),\n)',
  'empty-state-custom': '// Theme colors:\nfinal k = DsTheme.colorsOf(context);\nreturn DsEmptyState(\n  icon: const DsIcon(DsIcons.circleCheck),\n  title: const Text(\'All caught up\'),\n  description: const Text(\'You have read every message.\'),\n  style: DsEmptyStateStyle(\n    iconBoxColor: k.success.tint,\n    iconColor: k.success.text,\n    iconBoxSize: 56,\n    iconBoxRadius: BorderRadius.circular(28),\n    iconSize: 24,\n  ),\n)',
  'empty-state-minimal': 'const DsEmptyState(\n  title: Text(\'No activity this week\'),\n  description: Text(\'Changes your team makes show up here.\'),\n)',
  'empty-state-overview': 'DsCard(\n  style: const DsCardStyle(padding: EdgeInsets.zero),\n  child: DsEmptyState(\n    icon: const DsIcon(DsIcons.inbox),\n    title: const Text(\'No tasks yet\'),\n    description: const Text(\n      \'Add your first task or start from a template.\',\n    ),\n    actions: [\n      DsButton(\n        size: .sm,\n        onPressed: () {},\n        child: const Text(\'Add task\'),\n      ),\n      DsButton(\n        variant: .ghost,\n        size: .sm,\n        onPressed: () {},\n        child: const Text(\'Templates\'),\n      ),\n    ],\n  ),\n)',
  'empty-state-search': 'DsEmptyState(\n  icon: const DsIcon(DsIcons.searchX),\n  title: const Text(\'No matches for "invoice 2025"\'),\n  description: const Text(\n    \'Check the spelling or search all projects.\',\n  ),\n  actions: [\n    DsButton(\n      variant: .secondary,\n      size: .sm,\n      onPressed: () {},\n      child: const Text(\'Clear search\'),\n    ),\n  ],\n)',
  'empty-state-table': 'DsTable<String>(\n  semanticLabel: \'Members\',\n  rows: const [],\n  rowKey: (name) => name,\n  columns: [\n    DsTableColumn(id: \'name\', label: \'Name\', value: (n) => n),\n  ],\n  emptyView: DsEmptyState(\n    icon: const DsIcon(DsIcons.user),\n    title: const Text(\'No members match "Active"\'),\n    actions: [\n      DsButton(\n        variant: .ghost,\n        size: .xs,\n        onPressed: () {},\n        child: const Text(\'Show all members\'),\n      ),\n    ],\n  ),\n)',
  'field-custom': 'DsFieldTheme(\n  data: DsFieldThemeData(\n    style: DsFieldStyle(\n      labelStyle: const TextStyle(\n        fontSize: 14,\n        fontWeight: FontWeight.w500,\n      ),\n      labelGap: 8,\n    ),\n  ),\n  child: Column(\n    spacing: 16,\n    children: [\n      DsField(\n        label: const Text(\'First name\'),\n        child: DsTextField(initialValue: \'Ada\'),\n      ),\n      DsField(\n        label: const Text(\'Last name\'),\n        child: DsTextField(initialValue: \'Lovelace\'),\n      ),\n    ],\n  ),\n)',
