  'field-surface': 'DsField(\n  label: const Text(\'Label color\'),\n  errorText: color == null ? \'Pick a color.\' : null,\n  child: DsPressable(\n    onPressed: () => setState(() => _index = (_index + 1) % _colors.length),\n    semanticLabel: name,\n    builder: (context, states, _) => DsFieldSurface(\n      states: states,\n      child: Row(\n        spacing: 8,\n        children: [\n          Container(\n            width: 14,\n            height: 14,\n            decoration: BoxDecoration(\n              color: color ?? const Color(0x00000000),\n              shape: BoxShape.circle,\n            ),\n          ),\n          Expanded(child: Text(name)),\n          const DsIcon(DsIcons.chevronDown),\n        ],\n      ),\n    ),\n  ),\n)',
  'file-upload-accept': 'DsField(\n  label: const Text(\'Receipt\'),\n  errorText: _rejected,\n  child: DsFileUpload(\n    description: const Text(\'PDF, PNG or JPG · up to 10 MB\'),\n    onBrowse: () {\n      // Stands in for a picker that returned a large video.\n      const name = \'site-visit.mov\', bytes = 48200000;\n      final size = dsFormatFileSize(\n        bytes,\n        locale: Localizations.localeOf(context),\n      );\n      setState(() => _rejected = \'\$name is \$size. The limit is 10 MB.\');\n    },\n  ),\n)',
