  'forms-any': 'DsFormField<String>(\n  label: const Text(\'Billing\'),\n  description: const Text(\'Yearly saves two months.\'),\n  group: true,\n  initialValue: \'monthly\',\n  builder: (field) => DsSegmentedControl<String>(\n    value: field.value!,\n    onChanged: field.didChange,\n    semanticLabel: \'Billing\',\n    segments: const [\n      DsSegment(value: \'monthly\', label: Text(\'Monthly\')),\n      DsSegment(value: \'yearly\', label: Text(\'Yearly\')),\n    ],\n  ),\n)',
  'forms-overview': 'Form(\n  key: _form,\n  child: Column(\n    crossAxisAlignment: CrossAxisAlignment.start,\n    spacing: 20,\n    children: [\n      DsTextFormField(\n        label: const Text(\'Full name\'),\n        required: true,\n        autofillHints: const [AutofillHints.name],\n        textInputAction: TextInputAction.next,\n        validator: DsValidators.required(context),\n        onSaved: (v) => _account[\'name\'] = v,\n      ),\n      DsTextFormField(\n        label: const Text(\'Work email\'),\n        description: const Text(\'We send the confirmation here.\'),\n        required: true,\n        keyboardType: TextInputType.emailAddress,\n        autofillHints: const [AutofillHints.email],\n        textInputAction: TextInputAction.next,\n        validator: DsValidators.all([\n          DsValidators.required(context),\n          DsValidators.email(context),\n        ]),\n        onSaved: (v) => _account[\'email\'] = v,\n      ),\n      DsTextFormField(\n        label: const Text(\'Password\'),\n        required: true,\n        obscureText: true,\n        revealable: true,\n        autofillHints: const [AutofillHints.newPassword],\n        validator: DsValidators.all([\n          DsValidators.required(context),\n          DsValidators.minLength(context, 8),\n        ]),\n        onSaved: (v) => _account[\'password\'] = v,\n      ),\n      DsSelectFormField<String>(\n        label: const Text(\'Your role\'),\n        required: true,\n        placeholder: \'Choose a role\',\n        options: const [\n          DsSelectOption(value: \'eng\', label: \'Engineering\'),\n          DsSelectOption(value: \'design\', label: \'Design\'),\n          DsSelectOption(value: \'product\', label: \'Product\'),\n          DsSelectOption(value: \'other\', label: \'Something else\'),\n        ],\n        validator: DsValidators.required(context),\n        onSaved: (v) => _account[\'role\'] = v,\n      ),\n      DsNumberFormField(\n        label: const Text(\'Team size\'),\n        initialValue: 5,\n        min: 1,\n        max: 500,\n        unit: \'people\',\n        onSaved: (v) => _account[\'team\'] = v,\n      ),\n      DsDateFormField(\n        label: const Text(\'Trial starts\'),\n        description: const Text(\'Your 14-day trial begins on this day.\'),\n        firstDate: DateTime.now(),\n        required: true,\n        validator: DsValidators.required(context),\n        onSaved: (v) => _account[\'trialStart\'] = v,\n      ),\n      DsCheckboxFormField(\n        label: const Text(\'I agree to the terms of service\'),\n        required: true,\n        validator: DsValidators.required(\n          context,\n          message: \'Accept the terms to continue.\',\n        ),\n      ),\n      Wrap(\n        spacing: 12,\n        runSpacing: 12,\n        children: [\n          DsButton(\n            onPressed: _submit,\n            child: const Text(\'Create workspace\'),\n          ),\n          DsButton(\n            variant: .secondary,\n            onPressed: () => _form.currentState!.reset(),\n            child: const Text(\'Reset\'),\n          ),\n        ],\n      ),\n    ],\n  ),\n)',
  'forms-submit': 'void _submit() {\n  final form = _form.currentState!;\n  if (!form.validateAndFocus()) return;\n  form.save();\n  showDsToast(\n    context: context,\n    title: \'Workspace created\',\n    description: \'We sent a confirmation to \${_account[\'email\']}.\',\n    status: DsStatus.success,\n  );\n}',
  'forms-validators': 'DsTextFormField(\n  label: const Text(\'Username\'),\n  description: const Text(\'3 to 20 letters, digits or dashes.\'),\n  required: true,\n  autovalidateMode: AutovalidateMode.onUserInteraction,\n  validator: DsValidators.all([\n    DsValidators.required(context),\n    DsValidators.minLength(context, 3),\n    DsValidators.maxLength(context, 20),\n    (v) => RegExp(r\'^[a-zA-Z0-9-]*\$\').hasMatch(v!)\n        ? null\n        : \'Use only letters, digits and dashes.\',\n  ]),\n)',
  'glass-surface': 'DsSurface(\n  decoration: DsBoxDecoration(\n    color: k.overlay.withValues(alpha: .6),\n    borderRadius: BorderRadius.circular(t.radii.overlay),\n    shadows: t.shadows.overlay,\n  ),\n  backdropFilter: ImageFilter.blur(sigmaX: 24, sigmaY: 24),\n  padding: const EdgeInsets.fromLTRB(16, 10, 8, 10),\n  child: Row(\n    spacing: 12,\n    children: [\n      Expanded(\n        child: Text(\n          \'4 tasks selected\',\n          style: t.typography.bodyStrong.copyWith(color: k.text),\n        ),\n      ),\n      DsButton(\n        variant: .ghost,\n        size: .sm,\n        onPressed: () {},\n        child: const Text(\'Clear\'),\n      ),\n      DsButton(\n        size: .sm,\n        onPressed: () {},\n        child: const Text(\'Move\'),\n      ),\n    ],\n  ),\n)',
  'glass-themes': '// One translucent fill and one blur for every floating layer below.\nfinal fill = DsTheme.colorsOf(context).overlay.withValues(alpha: .6);\nfinal blur = ImageFilter.blur(sigmaX: 24, sigmaY: 24);\nreturn DsComponentThemes(\n  themes: [\n    DsMenuThemeData(\n      style: DsMenuStyle(background: fill, backdropFilter: blur),\n    ),\n    DsPopoverThemeData(\n      style: DsPopoverStyle(background: fill, backdropFilter: blur),\n    ),\n    DsToolbarThemeData(\n      style: DsToolbarStyle(background: fill, backdropFilter: blur),\n    ),\n  ],\n  child: child,\n)',
