  'link-custom': '// Muted until hovered, for a footer.\nfinal k = DsTheme.colorsOf(context);\nreturn DsLinkTheme(\n  data: DsLinkThemeData(\n    style: DsLinkStyle(\n      foreground: k.textMuted,\n      underlineWidth: 0,\n      hovered: DsLinkStyle(\n        foreground: k.text,\n        underlineWidth: 1,\n      ),\n    ),\n  ),\n  child: Wrap(\n    spacing: 20,\n    runSpacing: 12,\n    children: [\n      DsLink(label: \'Privacy\', onPressed: () {}),\n      DsLink(label: \'Terms\', onPressed: () {}),\n      DsLink(label: \'Contact\', onPressed: () {}),\n    ],\n  ),\n)',
