  'search-field-overview': 'DsSearchField(placeholder: \'Search tasks, people or files\'),\nDsSearchField(initialValue: \'invoice template\')',
  'search-field-shortcut': '// Ctrl+/ or ⌘/ focuses the search field, wherever focus is.\nfinal _search = FocusNode();\n\n@override\nvoid initState() {\n  super.initState();\n  HardwareKeyboard.instance.addHandler(_onKey);\n}\n\n@override\nvoid dispose() {\n  HardwareKeyboard.instance.removeHandler(_onKey);\n  _search.dispose();\n  super.dispose();\n}\n\nbool _onKey(KeyEvent event) {\n  final keys = HardwareKeyboard.instance;\n  if (event is KeyDownEvent &&\n      event.logicalKey == LogicalKeyboardKey.slash &&\n      (keys.isMetaPressed || keys.isControlPressed)) {\n    _search.requestFocus();\n    return true;\n  }\n  return false;\n}\n\n@override\nWidget build(BuildContext context) {\n  final apple =\n      defaultTargetPlatform == TargetPlatform.macOS ||\n      defaultTargetPlatform == TargetPlatform.iOS;\n  return DsSearchField(\n    focusNode: _search,\n    placeholder: \'Search the handbook\',\n    shortcut: apple ? \'⌘/\' : \'Ctrl+/\',\n  );\n}',
